use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let s = input.as_str().unwrap();
    let mut num = 0;
    let mut has_digit = false;
    for c in s.chars() {
        if c.is_digit(10) {
            num = num * 10 + c.to_digit(10).unwrap() as i64;
            has_digit = true;
        }
    }
    if !has_digit {
        return Value::Bool(false);
    }
    let mut sum = 0;
    let mut has_odd = false;
    for c in s.chars().rev() {
        if c.is_digit(10) {
            sum += c.to_digit(10).unwrap() as i64;
            has_odd = true;
        }
    }
    if !has_odd {
        return Value::Bool(false);
    }
    let mut doubled = num;
    while doubled > 0 {
        let digit = doubled % 10;
        doubled /= 10;
        if digit % 2 == 0 {
            sum += digit;
        } else {
            sum -= digit;
        }
    }
    Value::Bool(sum % 10 == 0)
}
